SELECT "t7"."line_id", "t7"."item_on_hand", COALESCE("t11"."quantity_on_hand", 0) AS "variant_on_hand"
FROM (SELECT "t2"."line_id", "t2"."request_number", "t2"."item", "t2"."quantity", "t2"."unit_price", "t2"."line_value", "t2"."reason", "t2"."requested_resolution", "t2"."requested_variant", "t2"."customer", "t2"."order_number", "t2"."requested_date", "t2"."customer_id", "t2"."addr", "t2"."cdemo", "t2"."hdemo", "t2"."birth_year", "t2"."center", "t6"."as_of_date", "t6"."quantity_on_hand", "t6"."_ttrp_g_n29_0", "t6"."_ttrp_g_n29_1", COALESCE("t6"."quantity_on_hand", 0) AS "item_on_hand"
        FROM (SELECT "t1"."line_id", "t1"."request_number", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."line_value", "t1"."reason", "t1"."requested_resolution", "t1"."requested_variant", "t1"."customer", "t1"."order_number", "t1"."requested_date", "customer"."customer_id", "customer"."addr", "customer"."cdemo", "customer"."hdemo", "customer"."birth_year", "customer"."center"
                FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "order_number", "requested_date"
                        FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                                FROM "return_request_line"
                                    INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                        WHERE "t"."state" = 'received') AS "t1"
                    INNER JOIN "customer" ON "t1"."customer" = "customer"."sk") AS "t2"
            LEFT JOIN (SELECT "t3"."as_of_date", "t3"."item", "t3"."warehouse", "t3"."quantity_on_hand", "t3"."_ttrp_g_n29_0", "t3"."_ttrp_g_n29_1"
                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n29_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n29_1"
                        FROM "inventory") AS "t3"
                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n29_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n29_1", MAX("as_of_date") AS "_ttrp_latest_n29"
                        FROM "inventory"
                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t5" ON "t3"."_ttrp_g_n29_0" = "t5"."_ttrp_g_n29_0" AND "t3"."_ttrp_g_n29_1" = "t5"."_ttrp_g_n29_1" AND "t3"."as_of_date" = "t5"."_ttrp_latest_n29") AS "t6" ON "t2"."item" = "t6"."item" AND "t2"."center" = "t6"."warehouse") AS "t7"
    LEFT JOIN (SELECT "t8"."as_of_date", "t8"."item", "t8"."warehouse", "t8"."quantity_on_hand", "t8"."_ttrp_g_n29_0", "t8"."_ttrp_g_n29_1"
        FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n29_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n29_1"
                FROM "inventory") AS "t8"
            INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n29_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n29_1", MAX("as_of_date") AS "_ttrp_latest_n29"
                FROM "inventory"
                GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t10" ON "t8"."_ttrp_g_n29_0" = "t10"."_ttrp_g_n29_0" AND "t8"."_ttrp_g_n29_1" = "t10"."_ttrp_g_n29_1" AND "t8"."as_of_date" = "t10"."_ttrp_latest_n29") AS "t11" ON "t7"."requested_variant" = "t11"."item" AND "t7"."center" = "t11"."warehouse"
